// BodyNotIn narrows to the rows whose body is none of vs.
func (s LineNote) BodyNotIn(vs ...string) LineNote {
	if len(vs) == 0 {
		return s
	}
	return LineNote{s.q.Where(`body NOT IN (`, impl.List(vs), `)`)}
}

